import{_ as s,o as n,c as e,a2 as p}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"项目一：整理你的电脑（入门级）","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-5/project-1.md","filePath":"modules/module-5/project-1.md"}'),t={name:"modules/module-5/project-1.md"};function l(i,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="项目一-整理你的电脑-入门级" tabindex="-1">项目一：整理你的电脑（入门级） <a class="header-anchor" href="#项目一-整理你的电脑-入门级" aria-label="Permalink to &quot;项目一：整理你的电脑（入门级）&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：通过整理电脑文件夹，掌握 Codex 的文件操作和自然语言指令能力<br> ⏱️ <strong>预计时长</strong>：20 分钟<br> 🎯 <strong>学到的能力</strong>：文件操作、自然语言指令、权限管理</p></blockquote><hr><h2 id="一、任务描述" tabindex="-1">一、任务描述 <a class="header-anchor" href="#一、任务描述" aria-label="Permalink to &quot;一、任务描述&quot;">​</a></h2><p>用 Codex 分析并整理电脑上一个杂乱的下载文件夹。</p><hr><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><ol><li>在你的电脑上创建一个测试文件夹，命名为&quot;待整理文件夹&quot;</li><li>往里面放入一些不同类型的文件（如果没有真实文件，可以手动创建几个）： <ul><li>几个文本文件（.txt）</li><li>几个图片文件（.jpg, .png）</li><li>几个 PDF 文件</li><li>几个 Excel 文件（.xlsx）</li><li>几个压缩包（.zip）</li></ul></li><li>也可以直接使用你电脑上的&quot;下载&quot;文件夹（建议先复制一份到桌面作为测试）</li></ol><hr><h2 id="三、操作步骤" tabindex="-1">三、操作步骤 <a class="header-anchor" href="#三、操作步骤" aria-label="Permalink to &quot;三、操作步骤&quot;">​</a></h2><h3 id="步骤-1-将文件夹设为-codex-的工作区" tabindex="-1">步骤 1：将文件夹设为 Codex 的工作区 <a class="header-anchor" href="#步骤-1-将文件夹设为-codex-的工作区" aria-label="Permalink to &quot;步骤 1：将文件夹设为 Codex 的工作区&quot;">​</a></h3><ol><li>打开 Codex 桌面 App</li><li>点击&quot;打开文件夹&quot;或&quot;选择工作区&quot;</li><li>找到你的&quot;待整理文件夹&quot;并确认</li></ol><h3 id="步骤-2-让-codex-分析文件夹" tabindex="-1">步骤 2：让 Codex 分析文件夹 <a class="header-anchor" href="#步骤-2-让-codex-分析文件夹" aria-label="Permalink to &quot;步骤 2：让 Codex 分析文件夹&quot;">​</a></h3><p>在对话框中输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我分析一下这个文件夹，告诉我：</span></span>
<span class="line"><span>1. 总共有多少个文件？</span></span>
<span class="line"><span>2. 按文件类型分类，各有多少个？</span></span>
<span class="line"><span>3. 最大的三个文件是什么？</span></span></code></pre></div><p>观察 Codex 的输出，了解文件夹的现状。</p><h3 id="步骤-3-让-codex-整理文件夹" tabindex="-1">步骤 3：让 Codex 整理文件夹 <a class="header-anchor" href="#步骤-3-让-codex-整理文件夹" aria-label="Permalink to &quot;步骤 3：让 Codex 整理文件夹&quot;">​</a></h3><p>输入指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请按文件类型帮我整理这个文件夹：</span></span>
<span class="line"><span>- 图片文件（.jpg, .png, .gif）移到 images 文件夹</span></span>
<span class="line"><span>- 文档文件（.pdf, .docx, .doc）移到 documents 文件夹</span></span>
<span class="line"><span>- 表格文件（.xlsx, .xls, .csv）移到 spreadsheets 文件夹</span></span>
<span class="line"><span>- 文本文件（.txt, .md）移到 text-files 文件夹</span></span>
<span class="line"><span>- 压缩文件（.zip, .rar, .7z）移到 archives 文件夹</span></span>
<span class="line"><span>- 其他文件移到 other 文件夹</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先告诉我你的计划，等我确认后你再执行。</span></span></code></pre></div><h3 id="步骤-4-审查-codex-的计划" tabindex="-1">步骤 4：审查 Codex 的计划 <a class="header-anchor" href="#步骤-4-审查-codex-的计划" aria-label="Permalink to &quot;步骤 4：审查 Codex 的计划&quot;">​</a></h3><p>Codex 会列出它的整理计划，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的整理计划：</span></span>
<span class="line"><span>1. 创建以下子文件夹：images/, documents/, spreadsheets/, text-files/, archives/, other/</span></span>
<span class="line"><span>2. 扫描所有文件并按扩展名分类</span></span>
<span class="line"><span>3. 将每个文件移动到对应的子文件夹</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请确认是否开始执行？</span></span></code></pre></div><p>点击&quot;允许&quot;或输入&quot;开始&quot;。</p><h3 id="步骤-5-验证结果" tabindex="-1">步骤 5：验证结果 <a class="header-anchor" href="#步骤-5-验证结果" aria-label="Permalink to &quot;步骤 5：验证结果&quot;">​</a></h3><p>整理完成后，检查文件夹结构是否正确：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>待整理文件夹/</span></span>
<span class="line"><span>├── images/</span></span>
<span class="line"><span>│   ├── photo1.jpg</span></span>
<span class="line"><span>│   └── screenshot.png</span></span>
<span class="line"><span>├── documents/</span></span>
<span class="line"><span>│   └── report.pdf</span></span>
<span class="line"><span>├── spreadsheets/</span></span>
<span class="line"><span>│   └── data.xlsx</span></span>
<span class="line"><span>├── text-files/</span></span>
<span class="line"><span>│   └── notes.txt</span></span>
<span class="line"><span>├── archives/</span></span>
<span class="line"><span>│   └── backup.zip</span></span>
<span class="line"><span>└── other/</span></span>
<span class="line"><span>    └── unknown.file</span></span></code></pre></div><hr><h2 id="四、进阶挑战" tabindex="-1">四、进阶挑战 <a class="header-anchor" href="#四、进阶挑战" aria-label="Permalink to &quot;四、进阶挑战&quot;">​</a></h2><p>如果上面的任务已经难不倒你，试试这些进阶指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找出所有超过 10MB 的文件，把它们单独放到一个&quot;大文件&quot;文件夹里</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>统计一下这个文件夹里有多少重复的文件名（忽略扩展名）</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我生成一份文件夹整理报告，保存到 reports.md 文件中</span></span></code></pre></div><hr><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>学到的能力</th><th>具体表现</th></tr></thead><tbody><tr><td>文件操作</td><td>读取、分类、移动文件</td></tr><tr><td>自然语言指令</td><td>用中文描述整理规则</td></tr><tr><td>权限管理</td><td>观察 Codex 如何征求你的同意</td></tr><tr><td>结果验证</td><td>检查整理结果是否符合预期</td></tr></tbody></table><hr><h2 id="六、下一步" tabindex="-1">六、下一步 <a class="header-anchor" href="#六、下一步" aria-label="Permalink to &quot;六、下一步&quot;">​</a></h2><p><a href="./project-2.html">→ 项目二：生成一份 PPT 报告</a></p>`,38)])])}const b=s(t,[["render",l]]);export{u as __pageData,b as default};
